_FALLBACK_SHORT_ARGS = set("ABCDEFGHJKQRTUWXabcdeEHoPrxYyzmou") | {"h"}
# The set above is deliberately generous; the live parser from curl --help all normally replaces it.


def usage_line() -> str:
    return f"Usage: {sys.argv[0]} {USAGE_TAIL}"


def load_curl_option_arities() -> Tuple[set, set]:
    """Return (long_options_with_arguments, short_options_with_arguments)."""
    long_args = set(_FALLBACK_LONG_ARGS)
    short_args = set(_FALLBACK_SHORT_ARGS)
    try:
        p = subprocess.run(["curl", "--help", "all"], stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, check=False)
        text = p.stdout.decode("utf-8", "replace")
    except Exception:
        return long_args, short_args
    parsed_long = set()
    parsed_short = set()
    for line in text.splitlines():
        if "--" not in line:
            continue
        mlong = re.search(r"(--[A-Za-z0-9_.-]+)", line)
        if not mlong:
            continue
        lname = mlong.group(1)
        rest = line[mlong.end():]
        # curl's help prints an argument immediately after the option name and it starts
        # with '<' or '['. No-argument descriptions begin with prose.
        stripped = rest.lstrip()
        takes_arg = bool(stripped and stripped[0] in "<[")
        if takes_arg:
            parsed_long.add(lname)
            mshort = re.search(r"^\s*(-.),\s*--", line)
            if mshort:
                parsed_short.add(mshort.group(1)[1])
    if parsed_long:
        long_args = parsed_long | {"--json"}  # curlie knows this newer curl option as taking data.
        short_args = parsed_short
    # Optional category, but curlie forwards a following token as the category if present.
    long_args.add("--help")
    short_args.add("h")
    return long_args, short_args


LONG_ARGS, SHORT_ARGS = load_curl_option_arities()


def shell_quote(arg: str) -> str:
    if re.search(r"\s", arg):
        return '"' + arg.replace('\\', '\\\\').replace('"', '\\"') + '"'
    return arg


def shell_join(args: List[str]) -> str:
    return " ".join(shell_quote(a) for a in args)


def go_escape_json_string(s: str) -> str:
    # Go's encoding/json emits UTF-8 but always HTML-escapes <, >, &, U+2028, U+2029.
    out = json.dumps(s, ensure_ascii=False, separators=(",", ":"))
    out = (out.replace("<", "\\u003c")
              .replace(">", "\\u003e")
              .replace("&", "\\u0026")
              .replace("\u2028", "\\u2028")
              .replace("\u2029", "\\u2029"))
    return out


def clean_exp(s: str) -> str:
    if "e" not in s and "E" not in s:
        return s
    mant, exp = re.split("[eE]", s, 1)
    sign = ""
    if exp.startswith(('+', '-')):
        sign, exp = exp[0], exp[1:]
    exp = exp.lstrip('0') or '0'
    if sign == '+':
        sign = ""
    return mant + "e" + sign + exp


def exp_to_fixed(rep: str) -> str:
    # Convert a shortest decimal in scientific form to fixed notation.
    mant, exp_s = re.split("[eE]", rep, 1)
    exp = int(exp_s)
    neg = mant.startswith('-')
    if neg:
        mant = mant[1:]
    if '.' in mant:
        intp, frac = mant.split('.', 1)
    else:
        intp, frac = mant, ''
    digits = intp + frac
    point = len(intp) + exp
    if point <= 0:
        res = "0." + "0" * (-point) + digits
    elif point >= len(digits):
        res = digits + "0" * (point - len(digits))
    else:
        res = digits[:point] + "." + digits[point:]
    if '.' in res:
        res = res.rstrip('0').rstrip('.')
    if neg:
        res = '-' + res
    return res


def go_format_float(f: float) -> str:
    if math.isnan(f) or math.isinf(f):
        return "null"
    if f == 0:
        return "0"
    af = abs(f)
    rep = repr(float(f))
    # Python's repr of an integer-valued float often includes .0.
    if rep.endswith('.0') and 'e' not in rep and 'E' not in rep:
        rep = rep[:-2]
    if 1e-6 <= af < 1e21:
        if 'e' in rep or 'E' in rep:
            return exp_to_fixed(rep)
        return rep
    # Exponential form, close to Go/json's cleaned exponent spelling.
    if 'e' not in rep and 'E' not in rep:
        rep = format(f, '.15e')
        mant, exp = rep.split('e')
        mant = mant.rstrip('0').rstrip('.')
        rep = mant + 'e' + exp
    return clean_exp(rep)


def go_json_dumps(v: Any) -> str:
    if v is None:
        return "null"
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, str):
        return go_escape_json_string(v)
    if isinstance(v, (int, float)) and not isinstance(v, bool):
        return go_format_float(float(v))
    if isinstance(v, list):
        return "[" + ",".join(go_json_dumps(x) for x in v) + "]"
    if isinstance(v, dict):
        parts = []
        for k in sorted(v.keys(), key=lambda x: str(x)):
            parts.append(go_escape_json_string(str(k)) + ":" + go_json_dumps(v[k]))
        return "{" + ",".join(parts) + "}"
    return go_escape_json_string(str(v))


def parse_raw_json(s: str) -> Any:
    try:
        return json.loads(s, parse_int=float, parse_float=float)
    except Exception:
        return None


def query_escape(s: str) -> str:
    return urllib.parse.quote_plus(s, safe='')


def normalize_display_url(original: str) -> str:
    if original.startswith("http"):
        return original
    if original.startswith("//"):
        return "http:" + original
    return "http://" + original


def normalize_curl_url(original: str) -> str:
    if original.startswith("//"):
        return original[2:]
    return original


def first_sep(item: str) -> Tuple[int, Optional[str]]:
    best = -1
    ch = None
    for c in (':', '='):
        i = item.find(c)
        if i >= 0 and (best < 0 or i < best):
            best = i
            ch = c
    return best, ch


def inspect_header_value(value: Optional[str], flags: Dict[str, bool]) -> None:
    if value is None:
        return
    i = value.find(':')
    if i < 0:
        return
    name = value[:i].lower()
    if name == "accept":
        flags["accept"] = True
    if name == "content-type":
        flags["content_type"] = True


class Parsed:
    def __init__(self) -> None:
        self.dry_run = False
        self.explicit_pretty = False
        self.pretty_active = False
        self.silent = False
        self.help_present = False
        self.url: Optional[str] = None
        self.display_url: Optional[str] = None
        self.query: List[Tuple[str, str]] = []
        self.method: Optional[str] = None
        self.option_args: List[str] = []
        self.request_args: List[str] = []
        self.data: Dict[str, Any] = {}
        self.form_mode = False
        self.form_fields = 0
        self.short_form_option = False
        self.short_data_body = False
        self.short_data_values: List[str] = []
        self.default_stdin_data = False
        self.flags = {"accept": False, "content_type": False}
        self.parse_messages: List[str] = []
        self.final_args: List[str] = []


def parse_args(argv: List[str]) -> Parsed:
    p = Parsed()
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--curl":
            p.dry_run = True
            i += 1
            continue
        if arg == "--pretty":
            p.explicit_pretty = True
            i += 1
            continue
        if arg == "--form":
            p.form_mode = True
            i += 1
            continue
        if arg == "-F":
            p.form_mode = True
            i += 1
            continue
        if arg == "-i":
            i += 1
            continue
        if arg == "--":
            i += 1
            continue

        if arg.startswith("--") and arg != "--":
            if "=" in arg:
                name = arg.split("=", 1)[0]
                p.option_args.append(arg)
                # Exact --silent only (not --silent=true) affects curlie's pretty -v default.
                # --header=... does not suppress curlie's default headers in the observed binary.
                i += 1
                continue
            name = arg
            p.option_args.append(arg)
            if name == "--silent":
                p.silent = True
            if name == "--verbose":
                pass
            if name == "--help":
                p.help_present = True
            if name in LONG_ARGS and i + 1 < len(argv):
                val = argv[i + 1]
                p.option_args.append(val)
                if name == "--header":
                    inspect_header_value(val, p.flags)
                i += 2
            else:
                i += 1
            continue

        if arg.startswith("-") and arg != "-" and len(arg) > 1:
            j = 1
            while j < len(arg):
                c = arg[j]
                if c == 'i':
                    j += 1
                    continue
                opt = "-" + c
                if c == 's':
                    p.silent = True
                    p.option_args.append(opt)
                    j += 1
                    continue
                if c in SHORT_ARGS:
                    p.option_args.append(opt)
                    rest = arg[j + 1:]
                    val = None
                    if rest:
                        val = rest
                        j = len(arg)
                    elif i + 1 < len(argv):
                        val = argv[i + 1]
                        i += 1
                        j = len(arg)
                    else:
                        j = len(arg)
                    if val is not None:
                        p.option_args.append(val)
                    if c == 'h':
                        p.help_present = True
                    if c == 'H':
                        inspect_header_value(val, p.flags)
                    if c == 'd':
                        p.short_data_body = True
                        if val is not None:
                            p.short_data_values.append(val)
                    if c == 'F':
                        p.short_form_option = True
                    break
                else:
                    p.option_args.append(opt)
                    j += 1
            i += 1
            continue

        # Positional: method, URL, or request item.
        if p.url is None and p.method is None and arg.upper() in METHODS:
            p.method = arg.upper()
            i += 1
            continue
        if p.url is None:
            p.url = normalize_curl_url(arg)
            p.display_url = normalize_display_url(arg)
            # The original leaks net/url parse errors to stdout for a few malformed inputs.
            if re.search(r"\s", p.display_url or "") and ":" in (p.display_url or ""):
                # Close enough for the common invalid-port case.
                p.parse_messages.append(f'parse "{p.display_url}": invalid port "{(p.display_url or "").split(":", 2)[-1]}" after host')
            i += 1
            continue

        idx, ch = first_sep(arg)
        if idx < 0:
            p.request_args.append(arg)
            i += 1
            continue
        if ch == ':':
            if idx + 1 < len(arg) and arg[idx + 1] == '=':
                key = arg[:idx]
                raw = arg[idx + 2:]
                p.data[key] = parse_raw_json(raw)
            else:
                p.request_args.extend(["-H", arg])
                inspect_header_value(arg, p.flags)
            i += 1
            continue
        # ch == '='
        if idx + 1 < len(arg) and arg[idx + 1] == '=':
            key = arg[:idx]
            val = arg[idx + 2:]
            p.query.append((key, val))
        else:
            if p.form_mode:
                p.request_args.extend(["-F", arg])
                p.form_fields += 1
            else:
                key = arg[:idx]
                val = arg[idx + 1:]
                p.data[key] = val
        i += 1

    if p.query and p.url is not None:
        qs = "&".join(query_escape(k) + "=" + query_escape(v) for k, v in p.query)
        sep_curl = "&" if "?" in p.url else "?"
        sep_disp = "&" if (p.display_url and "?" in p.display_url) else "?"
        p.url += sep_curl + qs
        p.display_url = (p.display_url or "") + sep_disp + qs

    p.pretty_active = p.explicit_pretty or sys.stdout.isatty()

    method_args: List[str] = []
    if p.method:
        if p.method == "HEAD":
            method_args = ["-I"]
        else:
            method_args = ["-X", p.method]

    data_args: List[str] = []
    if p.data:
        data_args = ["-d", go_json_dumps(p.data)]

    final: List[str] = []
    final.extend(p.option_args)
    final.extend(method_args)
    final.extend(p.request_args)
    final.extend(data_args)
    if p.url is not None:
        final.append(p.url)

    final.extend(["-s", "-S"])
    if p.pretty_active and not p.silent and not p.help_present:
        final.append("-v")

    stdin_not_tty = not sys.stdin.isatty()
    if stdin_not_tty and not p.help_present and not p.short_data_body and not p.data:
        final.append("-d@-")
        p.default_stdin_data = True

    has_formish = p.form_fields > 0 or p.short_form_option
    need_content_type = (p.default_stdin_data or p.short_data_body or bool(p.data)) and not has_formish
    if need_content_type and not p.flags["content_type"]:
        final.extend(["-H", "Content-Type: application/json"])
    if not p.flags["accept"]:
        final.extend(["-H", "Accept: application/json, */*"])

    p.final_args = final
    return p


def replace_usage(data: bytes) -> bytes:
    return data.replace(b"Usage: curl [options...] <url>", usage_line().encode())


def run_help_all() -> int:
    try:
        proc = subprocess.run(["curl", "--help", "all"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=False)
        sys.stdout.buffer.write(replace_usage(proc.stdout))
        sys.stderr.buffer.write(replace_usage(proc.stderr))
        return proc.returncode
    except FileNotFoundError:
        sys.stderr.write("curl: command not found\n")
        return 127


def has_verbose(args: List[str]) -> bool:
    return "-v" in args or "--verbose" in args


def has_stdin_data_arg(args: List[str]) -> bool:
    return "-d@-" in args or "--data@-" in args


def pretty_json_text_bytes(data: bytes) -> bytes:
    if not data:
        return data
    try:
        s = data.decode("utf-8")
    except UnicodeDecodeError:
        s = data.decode("utf-8", "replace")
    if not s or s[0] not in "[{":
        return data

    out: List[str] = []
    stack: List[Dict[str, Any]] = []
    indent = 0
    i = 0
    n = len(s)

    def spaces() -> str:
        return "    " * indent

    def current() -> Optional[Dict[str, Any]]:
        return stack[-1] if stack else None

    def parse_string(pos: int) -> Tuple[str, int]:
        j = pos + 1
        esc = False
        while j < n:
            ch = s[j]
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                j += 1
                return s[pos:j], j
            j += 1
        return s[pos:j], j

    balanced = False
    while i < n:
        ch = s[i]
        if ch in ' \t\r\n':
            i += 1
            continue
        if ch == '{' or ch == '[':
            out.append(WHITE + ch)
            stack.append({'type': 'object' if ch == '{' else 'array', 'expect_key': ch == '{'})
            indent += 1
            out.append("\n" + spaces())
            # This container is the value if it followed a colon.
            if len(stack) >= 2:
                parent = stack[-2]
                if parent.get('after_colon'):
                    parent['after_colon'] = False
            i += 1
            continue
        if ch == '}' or ch == ']':
            indent = max(indent - 1, 0)
            out.append("\n" + spaces() + WHITE + ch)
            if stack:
                stack.pop()
            if not stack:
                balanced = True
            i += 1
            continue
        if ch == ',':
            out.append(WHITE + ',' + "\n" + spaces())
            cur = current()
            if cur and cur['type'] == 'object':
                cur['expect_key'] = True
                cur['after_colon'] = False
            i += 1
            continue
        if ch == ':':
            out.append(WHITE + ': ')
            cur = current()
            if cur:
                cur['after_colon'] = True
                cur['expect_key'] = False
            i += 1
            continue
        if ch == '"':
            tok, ni = parse_string(i)
            cur = current()
            color = ""
            if cur and cur['type'] == 'object' and cur.get('expect_key'):
                color = BLUE
                cur['expect_key'] = False
            elif cur and cur.get('after_colon'):
                color = CYAN
                cur['after_colon'] = False
            elif cur and cur['type'] == 'array':
                color = BLUE
            out.append(color + tok if color else tok)
            i = ni
            continue
        # Number/literal/invalid token.
        j = i
        while j < n and s[j] not in ',:]}{[" \t\r\n':
            j += 1
        tok = s[i:j]
        cur = current()
        if cur and cur.get('after_colon'):
            if tok in ('true', 'false', 'null'):
                out.append(MAGENTA + tok)
            else:
                out.append(CYAN + tok)
            cur['after_colon'] = False
        else:
            out.append(tok)
        i = j if j > i else i + 1

    if balanced and not stack:
        out.append("\n" + RESET)
    return "".join(out).encode("utf-8")


def color_status_line(content: str) -> str:
    # content has no trailing \n, but usually keeps a trailing \r.
    m = re.match(r"^(HTTP)/(\S+)\s+(\d{3})(.*)$", content)
    if not m:
        return WHITE + content + RESET + "\n"
    return BLUE + m.group(1) + WHITE + "/" + CYAN + m.group(2) + " " + m.group(3) + YELLOW + m.group(4) + RESET + "\n"


def color_header_line(content: str) -> str:
    if content == "\r" or content == "":
        return content + "\n"
    if content.startswith("HTTP/"):
        return color_status_line(content)
    if ':' in content:
        name, val = content.split(':', 1)
        return WHITE + name + ':' + CYAN + val + RESET + "\n"
    return WHITE + content + RESET + "\n"


def filter_pretty_stderr(data: bytes) -> bytes:
    try:
        text = data.decode("utf-8", "replace")
    except Exception:
        text = data.decode("latin1", "replace")
    out: List[str] = []
    for raw in text.splitlines(True):
        line = raw[:-1] if raw.endswith('\n') else raw
        if line.startswith('< '):
            out.append(color_header_line(line[2:]))
        elif line.startswith('> ') or line.startswith('*') or line.startswith('{ ') or line.startswith('} '):
            continue
        elif line == "":
            continue
        else:
            # curl errors and other diagnostics.
            out.append(RED + line + RESET + ("\n" if raw.endswith('\n') else ""))
    return "".join(out).encode("utf-8")


def filter_verbose_stderr(data: bytes, body_echo: Optional[bytes]) -> bytes:
    out = bytearray()
    echoed = False
    for raw in data.splitlines(True):
        if raw.startswith(b'> '):
            out.extend(raw[2:])
        elif raw.startswith(b'< '):
            out.extend(raw[2:])
        elif raw.startswith(b'} '):
            if body_echo is not None and not echoed:
                out.extend(body_echo)
                out.extend(b"\n\n")
                echoed = True
        elif raw.startswith(b'{ '):
            continue
        else:
            out.extend(raw)
    return bytes(out)


def run_curl(parsed: Parsed) -> int:
    curl_cmd = ["curl"] + parsed.final_args

    if parsed.dry_run:
        for msg in parsed.parse_messages:
            sys.stdout.write(msg)
        sys.stdout.write(shell_join(curl_cmd) + "\n")
        if parsed.display_url:
            sys.stderr.write(parsed.display_url + "\n")
        return 0

    if parsed.display_url:
        sys.stderr.write(parsed.display_url + "\n")
        sys.stderr.flush()

    capture_for_usage = parsed.help_present
    verbose = has_verbose(parsed.final_args)
    pretty = parsed.pretty_active
    need_capture = capture_for_usage or pretty or verbose

    stdin_data: Optional[bytes] = None
    stdin_pipe = False
    if need_capture and has_stdin_data_arg(parsed.final_args):
        try:
            stdin_data = sys.stdin.buffer.read()
        except Exception:
            stdin_data = b""
        stdin_pipe = True

    body_echo: Optional[bytes] = None
    if parsed.data:
        body_echo = go_json_dumps(parsed.data).encode()
    elif parsed.short_data_values:
        # curlie echoes short -d data in verbose mode. Multiple -d options are rare; curl joins them with '&'.
        body_echo = b"&".join(v.encode() for v in parsed.short_data_values)
    elif parsed.default_stdin_data and stdin_data is not None:
        body_echo = stdin_data

    try:
        if not need_capture:
            proc = subprocess.run(curl_cmd, check=False)
            return proc.returncode
        proc = subprocess.Popen(
            curl_cmd,
            stdin=subprocess.PIPE if stdin_pipe else None,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
        )
        out, err = proc.communicate(stdin_data if stdin_pipe else None)
    except FileNotFoundError:
        sys.stderr.write("curl: command not found\n")
        return 127

    if capture_for_usage:
        sys.stdout.buffer.write(replace_usage(out))
        sys.stderr.buffer.write(replace_usage(err))
    elif pretty:
        sys.stderr.buffer.write(filter_pretty_stderr(err))
        sys.stdout.buffer.write(pretty_json_text_bytes(out))
    elif verbose:
        sys.stderr.buffer.write(filter_verbose_stderr(err, body_echo))
        sys.stdout.buffer.write(out)
    return proc.returncode


def main() -> int:
    argv = sys.argv[1:]
    if not argv:
        return run_help_all()
    parsed = parse_args(argv)
    return run_curl(parsed)


if __name__ == "__main__":
    raise SystemExit(main())
